UPDATE _fodynest_schema_tmp SET s = s || '{"locale":"it","nx_ui_lang":"it","nx_choice_cards":true,"goNextPageAutomatic":true,"allowCompleteSurveyAutomatic":false,"textUpdateMode":"onTyping","showProgressBar":"off","showQuestionNumbers":"off","questionsOnPageMode":"standard","requiredText":"*","pagePrevText":"Indietro","pageNextText":"Avanti","completeText":"Invia le risposte","nx_paradata":true,"nx_no_client_meta":true,"nx_coarse_device":true,"nx_no_probe":["n2_2","n2_3","n2_4","n2_5"],"pages":[{"name":"intro","elements":[{"type":"html","name":"intro_testo","html":"<p style=\"margin:0 0 12px;line-height:1.55\">Questo questionario fa parte di uno studio su FODYNEST.</p><p style=\"margin:0 0 12px;line-height:1.55\">Lo studio confronta <strong style=\"color:#286181\">che cosa chi ha fatto il gioco vuole trasmettere</strong> con che cosa arriva davvero a chi ci gioca.</p><p style=\"margin:0 0 12px;line-height:1.55\">Non ci sono risposte giuste: ci interessa che cosa pensi tu. Meglio frasi concrete che formule generali.</p><p style=\"margin:0 0 12px;line-height:1.55\"><strong style=\"color:#286181\">Rispondi senza consultarti con l&#x27;altra designer e le persone di FODY.</strong> Anche le differenze tra le vostre risposte sono un dato.</p><p style=\"margin:0 0 12px;line-height:1.55\">Ci vogliono circa 30-40 minuti. Puoi interrompere e riprendere dallo stesso dispositivo entro 14 giorni.</p><p style=\"margin:0 0 12px;line-height:1.55\"><strong style=\"color:#286181\">Le tue risposte non sono anonime.</strong> Le leggono solo Vittorio Guerrieri e Raluca Fulgu, per NexLudica APS. FODY e l&#x27;altra designer non le vedono.</p><p style=\"margin:0 0 12px;line-height:1.55\">Su OSF depositiamo il testo integrale delle tue risposte, con un codice al posto del nome, <strong style=\"color:#286181\">solo se lo autorizzi qui sotto</strong>.</p><p style=\"margin:0 0 12px;line-height:1.55\">Partecipare è libero: puoi ritirarti quando vuoi, senza conseguenze sui tuoi rapporti con NexLudica o con FODY.</p><details style=\"margin:6px 0 16px;border:1px solid #cfd8dc;border-radius:10px\"><summary style=\"cursor:pointer;padding:12px 14px;font-weight:600;color:#286181\">Dettagli su come trattiamo i dati</summary><div style=\"padding:2px 14px 6px;font-size:0.95em\"><p style=\"margin:0 0 10px;line-height:1.5\"><strong style=\"color:#286181\">Titolare</strong>: NexLudica APS, Vico Barnabiti 10, 16122 Genova, info@nexludica.org. Responsabile scientifico: Vittorio Guerrieri.</p><p style=\"margin:0 0 10px;line-height:1.5\"><strong style=\"color:#286181\">Finalità</strong>: lo studio descritto sopra. I risultati andranno in un articolo scientifico e in un rapporto per le designer e per FODY.</p><p style=\"margin:0 0 10px;line-height:1.5\"><strong style=\"color:#286181\">Dati</strong>: quale delle due designer sei, le tue risposte, data e ora di invio, il tempo passato su ogni pagina e il tipo di dispositivo. Non salviamo l&#x27;indirizzo IP né dati del browser.</p><p style=\"margin:0 0 10px;line-height:1.5\"><strong style=\"color:#286181\">Base giuridica</strong>: il tuo consenso (art. 6.1.a GDPR), che puoi revocare in ogni momento.</p><p style=\"margin:0 0 10px;line-height:1.5\"><strong style=\"color:#286181\">Chi li tratta</strong>: Vittorio Guerrieri e Raluca Fulgu, autorizzati da NexLudica. Il questionario funziona su Cloudflare, Inc. (USA), che tratta i dati per conto di NexLudica: il database si trova in una regione europea, e gli eventuali trasferimenti verso gli USA si basano sul Data Privacy Framework UE-USA e sulle clausole contrattuali standard.</p><p style=\"margin:0 0 10px;line-height:1.5\"><strong style=\"color:#286181\">Pubblicazione su OSF</strong>: se lo autorizzi, prima delle partite depositiamo su OSF (archivio a Francoforte) il testo integrale delle tue risposte, con un codice al posto del nome; la corrispondenza tra codici e nomi la conosciamo solo noi. Prima del deposito ti facciamo rileggere il testo. Chi conosce il gioco sa chi l&#x27;ha fatto: il codice non rende le risposte del tutto anonime. La registrazione diventa pubblica al più tardi dopo 4 anni, e ciò che è pubblicato non si può più ritirare. Se non lo autorizzi, depositiamo solo l&#x27;elenco dei messaggi ricavati dalle tue risposte, con il codice, e un&#x27;impronta digitale del file che prova che le risposte non sono state cambiate.</p><p style=\"margin:0 0 10px;line-height:1.5\"><strong style=\"color:#286181\">Conservazione</strong>: le risposte restano sulla piattaforma fino alla fine dell&#x27;analisi e comunque non oltre il 31 dicembre 2027. Poi le conserviamo in un archivio protetto di NexLudica per 5 anni dalla pubblicazione dell&#x27;articolo.</p><p style=\"margin:0 0 10px;line-height:1.5\"><strong style=\"color:#286181\">Rischi</strong>: i risultati potrebbero mostrare che il gioco trasmette meno di quanto speravi. Prima della pubblicazione li riceverai e potrai commentarli; il tuo commento sarà riportato.</p><p style=\"margin:0 0 10px;line-height:1.5\"><strong style=\"color:#286181\">Diritti</strong>: accesso, rettifica, cancellazione, limitazione, opposizione, portabilità e revoca del consenso, scrivendo a info@nexludica.org. Se revochi prima del deposito su OSF cancelliamo tutto; dopo, cancelliamo tutto ciò che non è già pubblicato. Puoi proporre reclamo al Garante per la protezione dei dati personali (garanteprivacy.it).</p></div></details>"},{"type":"boolean","name":"consent_partecipazione","renderAs":"checkbox","titleLocation":"hidden","title":"Ho letto queste informazioni e accetto di partecipare allo studio.","label":"Ho letto queste informazioni e accetto di partecipare allo studio.","isRequired":true,"requiredErrorText":"Per andare avanti spunta la casella."},{"type":"boolean","name":"consent_dati","renderAs":"checkbox","titleLocation":"hidden","title":"Acconsento al trattamento dei miei dati personali come descritto.","label":"Acconsento al trattamento dei miei dati personali come descritto.","isRequired":true,"requiredErrorText":"Per andare avanti spunta la casella."},{"type":"boolean","name":"osf_integrale","renderAs":"checkbox","titleLocation":"hidden","title":"Deposito integrale su OSF","label":"Facoltativo: autorizzo il deposito su OSF del testo integrale delle mie risposte, con un codice al posto del nome, dopo averlo riletto."}],"title":"Prima di iniziare"},{"name":"p_chi","elements":[{"type":"radiogroup","name":"chi_compila","title":"Chi sta compilando?","choices":[{"value":1,"text":"Letizia Vaccarella"},{"value":2,"text":"Giulia Teverini"}],"isRequired":true,"requiredErrorText":"Questa risposta serve per andare avanti."}],"title":"Chi compila"},{"name":"p_n1","elements":[{"type":"comment","name":"n1","title":"Immagina una persona che ha appena finito una partita a FODYNEST. Se dovesse dire in una frase che cosa le ha lasciato il gioco, quale frase vorresti sentire?","rows":5,"autoGrow":true,"allowResize":false}],"title":"Che cosa vuoi trasmettere"},{"name":"p_n2","elements":[{"type":"panel","name":"n2_panel","title":"Elenca fino a cinque cose (idee, conoscenze, atteggiamenti) che vorresti arrivassero a chi gioca, in ordine di importanza.","description":"Una per casella: appena ne scrivi una, compare la casella per la successiva.","elements":[{"type":"comment","name":"n2_1","title":"Prima cosa","rows":2,"autoGrow":true,"allowResize":false},{"type":"comment","name":"n2_2","title":"Seconda cosa","rows":2,"autoGrow":true,"allowResize":false,"visibleIf":"{n2_1} notempty"},{"type":"comment","name":"n2_3","title":"Terza cosa","rows":2,"autoGrow":true,"allowResize":false,"visibleIf":"{n2_2} notempty"},{"type":"comment","name":"n2_4","title":"Quarta cosa","rows":2,"autoGrow":true,"allowResize":false,"visibleIf":"{n2_3} notempty"},{"type":"comment","name":"n2_5","title":"Quinta cosa","rows":2,"autoGrow":true,"allowResize":false,"visibleIf":"{n2_4} notempty"}]}]},{"name":"p_n3","elements":[{"type":"comment","name":"n3","title":"Che idea di impresa sociale nel tessile vorresti c